// --- 5. the lenient urlsplit shapes (the pyurl pin) ----------------------

var goldenURLShapes = []string{
	"plain", "userinfo_port", "ipv6", "uppercase_scheme", "space_in_host",
	"not_a_url", "protocol_relative", "chrome_error", "about_blank",
	"raw_unicode_host", "empty", "just_scheme", "port_only_colon",
	"at_sign_no_host", "multiple_at", "bracket_no_close",
}

var goldenURLInputs = map[string]string{
	"plain":             "https://walled.example.net/article",
	"userinfo_port":     "https://user:pw@Example.COM:8443/p?q#f",
	"ipv6":              "http://[::1]:8080/x",
	"uppercase_scheme":  "HTTP://EXAMPLE.NET/",
	"space_in_host":     "https://host with space/x",
	"not_a_url":         "not a url",
	"protocol_relative": "//host/path",
	"chrome_error":      "chrome-error://chromewebdata/",
	"about_blank":       "about:blank",
	"raw_unicode_host":  "https://\u4f8b\u3048.\u30c6\u30b9\u30c8/path",
	"empty":             "",
	"just_scheme":       "https://",
	"port_only_colon":   "https://example.com:/x",
	"at_sign_no_host":   "https://@example.com/x",
	"multiple_at":       "https://a@b@example.com/x",
	"bracket_no_close":  "http://[::1/x",
}

func TestGoldenURLShapes(t *testing.T) {
	g := chromeSection(t, "url_shapes")
	for _, name := range goldenURLShapes {
		want, ok := g[name].(map[string]any)
		if !ok {
			t.Fatalf("golden url shape %q missing", name)
		}
		scheme, hostname, hasNetloc := pyURLParts(goldenURLInputs[name])
		if _, isError := want["error"]; isError {
			// urlparse raised — the callers' except reads "no parse"
			cmpGolden(t, "url_shapes."+name+".error",
				[]any{scheme, hostname, hasNetloc},
				[]any{"", "", false})
			continue
		}
		// Python's hostname None and Go's "" are the same "no host"
		wantHostname := ""
		if v, ok := want["hostname"].(string); ok {
			wantHostname = v
		}
		wantScheme := ""
		if v, ok := want["scheme"].(string); ok {
			wantScheme = v
		}
		cmpGolden(t, "url_shapes."+name, map[string]any{
			"scheme":          scheme,
			"hostname":        hostname,
			"netloc_nonempty": hasNetloc,
		}, map[string]any{
			"scheme":          wantScheme,
			"hostname":        wantHostname,
			"netloc_nonempty": want["netloc"] != "",
		})
	}
}

// --- 6. the loopback law --------------------------------------------------

func TestGoldenLoopbackLaw(t *testing.T) {
	g := chromeSection(t, "loopback_law")
	for name, u := range map[string]string{
		"localhost":       "http://localhost:3000/x",
		"localhost_upper": "http://LOCALHOST:9/x",
		"ipv4":            "http://127.0.0.1:9/x",
		"ipv6_brackets":   "http://[::1]:9/x",
		"ipv6_bare":       "http://::1:9/x",
		"dot_local":       "https://machine.local/y",
		"sub_local":       "https://a.machine.local/y",
		"not_local":       "https://walled.example.net/article",
		"empty":           "",
		"no_netloc":       "about:blank",
	} {
		want, ok := g[name]
		if !ok {
			t.Fatalf("golden loopback case %q missing", name)
		}
		cmpGolden(t, "loopback_law."+name, IsLoopbackURL(u), want)
	}
}

